/// UPDATE = `rtreeDeleteRowid` + insert of the new cell; a rowid change, UPDATE OR REPLACE onto an existing id.
#[test]
fn rtree_update_coordinates_and_rowid_1024() {
    assert_file_is_what_c_writes(
        "rtree_update_coordinates_and_rowid_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE VIRTUAL TABLE b USING rtree(id, x0, x1, y0, y1);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<900) INSERT INTO b SELECT x, (x*7919)%1000, (x*7919)%1000 + (x*13)%9, (x*104729)%1000, (x*104729)%1000 + (x*17)%7 FROM c;",
            "UPDATE b SET x0 = x0 - 3, x1 = x1 + 300 WHERE id % 7 = 0;",
            "UPDATE b SET id = id + 5000 WHERE id % 11 = 0;",
            "UPDATE OR REPLACE b SET id = id + 1 WHERE id < 60;",
            "UPDATE b SET y0 = 0, y1 = 1000 WHERE id BETWEEN 100 AND 130;",
        ],
        52224,
        0xf15ca9152915f342,
    );
}

/// rtree_i32 with auxiliary columns: the `_rowid` row is written by the UPSERT of `pWriteRowid`, then by `pWriteAux`; values reach xUpdate without column affinity.
#[test]
fn rtree_i32_aux_columns_1024() {
    assert_file_is_what_c_writes(
        "rtree_i32_aux_columns_1024",
        &[
            "PRAGMA page_size=1024;",
            "CREATE VIRTUAL TABLE b USING rtree_i32(id, x0, x1, y0, y1, +tag, +note TEXT);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<700) INSERT INTO b SELECT x, (x*7919)%1000, (x*7919)%1000 + (x*13)%9, (x*104729)%1000, (x*104729)%1000 + (x*17)%7, x%5, 'n'||(x%13) FROM c;",
            "UPDATE b SET tag = 'upd' WHERE id % 9 = 0;",
            "UPDATE b SET x0 = x0 - 1, note = NULL WHERE id % 10 = 0;",
            "DELETE FROM b WHERE id % 4 = 1;",
            "INSERT INTO b VALUES(NULL, 1, 2, 3, 4, 5, 6), (NULL, '7', 8.9, '1e1', 20, x'00', 3.5);",
        ],
        44032,
        0x50d08fdd000c61e1,
    );
}

