/// a page taken off the free list is fetched with PAGER_GET_NOCONTENT: `sqlite3PagerGet` marks it in the in-journal bit vector of the transaction and of every open savepoint (`addToSavepointBitvecs`), so neither journal keeps its old image and `ROLLBACK TO` leaves the bytes the statement wrote into it (plain tables, no R-Tree).
#[test]
fn free_list_page_reused_inside_a_savepoint_is_not_restored() {
    assert_file_is_what_c_writes(
        "free_list_page_reused_inside_a_savepoint_is_not_restored",
        &[
            "PRAGMA page_size=1024;",
            "CREATE TABLE a(x);",
            "CREATE TABLE k(y);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<40) INSERT INTO a SELECT printf('%0900d', x) FROM c;",
            "DELETE FROM a;",
            "BEGIN;",
            "INSERT INTO k VALUES(1);",
            "SAVEPOINT s;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<12) INSERT INTO a SELECT printf('%0700d', x + 500) FROM c;",
            "ROLLBACK TO s;",
            "INSERT INTO k VALUES(2);",
            "COMMIT;",
        ],
        44032,
        0xb351f0136301a213,
    );
}

