/// changes() / total_changes() / last_insert_rowid(): the statements the module runs on its shadow tables are counted like any statement (`sqlite3VdbeHalt`), their inserts set `db->lastRowid`.
#[test]
fn rtree_counters_follow_the_nested_statements() {
    assert_rows_and_errors_are_what_c_returns(
        "rtree_counters_follow_the_nested_statements",
        &[
            "CREATE VIRTUAL TABLE rt USING rtree(id, x1, x2, y1, y2);",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "INSERT INTO rt VALUES(5,1,2,3,4);",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "INSERT INTO rt VALUES(NULL,1,2,3,4);",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "INSERT INTO rt VALUES(7,1,2,3,4),(8,2,3,4,5);",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "UPDATE rt SET x1=0 WHERE id=7;",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "UPDATE rt SET id=70 WHERE id=7;",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "DELETE FROM rt WHERE id=8;",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "INSERT INTO rt VALUES(5,1,2,3,4);",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "INSERT OR REPLACE INTO rt VALUES(5,1,2,3,9);",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "INSERT INTO rt VALUES(9,5,2,3,9);",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "INSERT INTO rt VALUES(100,1,2,3,4),(5,1,2,3,4);",
            "SELECT changes(), total_changes(), last_insert_rowid();",
            "DELETE FROM rt;",
            "SELECT changes(), total_changes(), last_insert_rowid();",
        ],
        "1|1|1\n1|4|5\n1|8|6\n2|14|8\n1|19|1\n1|24|1\n1|27|1\n0|27|1\n1|32|5\n0|32|5\n0|34|100\n3|43|1\n",
        &[
            "UNIQUE constraint failed: rt.id",
            "rtree constraint failed: rt.(x1<=x2)",
            "UNIQUE constraint failed: rt.id",
        ],
    );
}

