/// an OR conjunct on a virtual table (where.c `whereLoopAddOr`): MULTI-INDEX OR when the LogEst sum of the branch costs + 1 is below the single scan — each branch costed with the other terms of the WHERE clause too (`allocateIndexInfo` walks `pOuter`); `x=A OR x=B` is an IN; two branches sharing `x op A` give the virtual term of `whereCombineDisjuncts`; rows come branch by branch.
#[test]
fn rtree_or_plans_follow_the_cost_model() {
    assert_rows_and_errors_are_what_c_returns(
        "rtree_or_plans_follow_the_cost_model",
        &[
            "CREATE VIRTUAL TABLE t USING rtree(id,c0,c1,c2,c3);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<600) INSERT INTO t SELECT x, x%20, x%20+1, x%17, x%17+2 FROM c;",
            "EXPLAIN QUERY PLAN SELECT id FROM t WHERE (c0 > 5 AND c1 < 9) OR c0 = 5;",
            "EXPLAIN QUERY PLAN SELECT id FROM t WHERE (c0 > 5) OR c0 = 5;",
            "EXPLAIN QUERY PLAN SELECT id FROM t WHERE (c0 > 5 OR c2 = 5) AND c3 > 1;",
            "EXPLAIN QUERY PLAN SELECT id FROM t WHERE ((c0 > 5 AND c1 < 9) OR c2 = 5) AND c3 > 1;",
            "EXPLAIN QUERY PLAN SELECT id FROM t WHERE (id = 3 AND c2 < 3) OR (id = 3 AND c3 > 17);",
            "EXPLAIN QUERY PLAN SELECT id, c1 FROM t WHERE (id = 170) OR id IN (72);",
            "EXPLAIN QUERY PLAN SELECT id FROM t WHERE (c0 < -8 AND 3.5 <= c0 AND 0 = c0 AND c1 = 7) OR id = 68;",
            "EXPLAIN QUERY PLAN SELECT id FROM t WHERE c2 = 5 AND c2 > 3 AND c0 < c2;",
            "SELECT group_concat(id, ' ') FROM (SELECT id FROM t WHERE (c0 > 17 AND c1 < 20) OR c2 = 5);",
            "SELECT group_concat(id, ' ') FROM (SELECT id FROM t WHERE (c0 < 2 AND c2 < 3) OR (c0 <= 2 AND c3 > 17));",
            "SELECT id FROM t WHERE (id = 170) OR id IN (72);",
        ],
        "MULTI-INDEX OR\nINDEX 1\nSCAN t VIRTUAL TABLE INDEX 2:E0C1\nINDEX 2\nSCAN t VIRTUAL TABLE INDEX 2:A0\nSCAN t VIRTUAL TABLE INDEX 2:D0\nSCAN t VIRTUAL TABLE INDEX 2:E3\nMULTI-INDEX OR\nINDEX 1\nSCAN t VIRTUAL TABLE INDEX 2:E0C1E3\nINDEX 2\nSCAN t VIRTUAL TABLE INDEX 2:A2E3\nSCAN t VIRTUAL TABLE INDEX 1:\nSCAN t VIRTUAL TABLE INDEX 1:\nMULTI-INDEX OR\nINDEX 1\nSCAN t VIRTUAL TABLE INDEX 2:C0D0A0A1\nINDEX 2\nSCAN t VIRTUAL TABLE INDEX 1:\nSCAN t VIRTUAL TABLE INDEX 2:A2E2C0\n238 358 18 138 478 578 298 78 198 418 538 598 258 38 378 458 438 338 118 218 98 318 558 498 158 278 398 58 518 178 260 141 481 600 566 549 447 430 107 90 209 226 328 362 22 243 124 345 5 464 583 413 311 294 73 192 532 515 396 379 175 56 39 277\n460 340 240 120 461 341 221 121 1 561 580 322 101 220 441 560\n72\n170\n",
        &[],
    );
}

/// ORDER BY compares -0.0 and 0.0 as equal (an r-tree keeps the sign of a zero coordinate, so such keys now reach the sorter).
#[test]
fn order_by_treats_negative_zero_as_zero() {
    assert_rows_and_errors_are_what_c_returns(
        "order_by_treats_negative_zero_as_zero",
        &[
            "CREATE VIRTUAL TABLE t USING rtree(id,c0,c1);",
            "INSERT INTO t VALUES(5,-0.0,1),(2,0.0,1),(9,-0.0,2),(1,0,3);",
            "SELECT id FROM t WHERE c1>0 OR c0<-5 ORDER BY c0, id;",
            "SELECT y FROM (SELECT -0.0 AS x, 2 AS y UNION ALL SELECT 0.0, 1) ORDER BY x, y;",
        ],
        "1\n2\n5\n9\n1\n2\n",
        &[],
    );
}

/// ALTER TABLE on an r-tree: catalogue text after RENAME, the messages of the refused forms (`isRealTable`: cannot rename columns of virtual table "x"), and `rtreeCheckTable`: a table that cannot be prepared fails with the bare result code (SQL logic error), fewer than three columns is "Schema corrupt or not an rtree", the argument count is checked when the function runs; a rename whose xRename fails (`rtreeRename` returns the bare result code of `sqlite3_exec`: SQL logic error) is rolled back as a whole.
#[test]
fn rtree_alter_messages_and_rtreecheck_front_end() {
    assert_rows_and_errors_are_what_c_returns(
        "rtree_alter_messages_and_rtreecheck_front_end",
        &[
            "CREATE TABLE t1(a);",
            "CREATE TABLE t3(a,b,c);",
            "CREATE VIRTUAL TABLE r USING rtree(id,x0,x1);",
            "CREATE VIRTUAL TABLE ri USING rtree_i32(id,x0,x1,y0,y1,+u,+v);",
            "INSERT INTO r VALUES(1,2,3);",
            "INSERT INTO ri VALUES(1,2,3,4,5,'a','b');",
            "CREATE VIEW vr AS SELECT id FROM r;",
            "ALTER TABLE r RENAME TO \"r 2\";",
            "ALTER TABLE ri RENAME COLUMN x0 TO q;",
            "ALTER TABLE ri ADD COLUMN q;",
            "ALTER TABLE ri DROP COLUMN x0;",
            "ALTER TABLE ri RENAME TO t1;",
            "SELECT name, sql FROM sqlite_schema ORDER BY rowid;",
            "PRAGMA schema_version;",
            "SELECT * FROM vr;",
            "SELECT rtreecheck('r 2'), rtreecheck('ri'), rtreecheck('main','ri');",
            "SELECT rtreecheck('nosuch');",
            "SELECT rtreecheck('t1');",
            "SELECT rtreecheck('t3');",
            "SELECT rtreecheck('nodb','ri');",
            "SELECT rtreecheck('ri_rowid');",
            "SELECT rtreecheck(NULL);",
            "SELECT rtreecheck(1,2,3);",
            "CREATE TABLE q2_node(x);",
            "ALTER TABLE ri RENAME TO q2;",
            "SELECT name FROM sqlite_schema ORDER BY rowid;",
            "SELECT * FROM ri;",
            "BEGIN;",
            "INSERT INTO ri VALUES(2,2,3,4,5,'c','d');",
            "ALTER TABLE ri RENAME TO q2;",
            "INSERT INTO ri VALUES(3,2,3,4,5,'e','f');",
            "COMMIT;",
            "SELECT * FROM ri;",
            "PRAGMA schema_version;",
        ],
        "t1|CREATE TABLE t1(a)\nt3|CREATE TABLE t3(a,b,c)\nr 2|CREATE VIRTUAL TABLE \"r 2\" USING rtree(id,x0,x1)\nr 2_rowid|CREATE TABLE \"r 2_rowid\"(rowid INTEGER PRIMARY KEY,nodeno)\nr 2_node|CREATE TABLE \"r 2_node\"(nodeno INTEGER PRIMARY KEY,data)\nr 2_parent|CREATE TABLE \"r 2_parent\"(nodeno INTEGER PRIMARY KEY,parentnode)\nri|CREATE VIRTUAL TABLE ri USING rtree_i32(id,x0,x1,y0,y1,+u,+v)\nri_rowid|CREATE TABLE \"ri_rowid\"(rowid INTEGER PRIMARY KEY,nodeno,a0,a1)\nri_node|CREATE TABLE \"ri_node\"(nodeno INTEGER PRIMARY KEY,data)\nri_parent|CREATE TABLE \"ri_parent\"(nodeno INTEGER PRIMARY KEY,parentnode)\nvr|CREATE VIEW vr AS SELECT id FROM \"r 2\"\n12\n1\nok|ok|ok\nSchema corrupt or not an rtree\nt1\nt3\nr 2\nr 2_rowid\nr 2_node\nr 2_parent\nri\nri_rowid\nri_node\nri_parent\nvr\nq2_node\n1|2|3|4|5|a|b\n1|2|3|4|5|a|b\n2|2|3|4|5|c|d\n3|2|3|4|5|e|f\n13\n",
        &[
            "cannot rename columns of virtual table \"ri\"",
            "virtual tables may not be altered",
            "cannot drop column from virtual table \"ri\"",
            "there is already another table or index with this name: t1",
            "SQL logic error",
            "SQL logic error",
            "SQL logic error",
            "SQL logic error",
            "SQL logic error",
            "wrong number of arguments to function rtreecheck()",
            "SQL logic error",
            "SQL logic error",
        ],
    );
}

/// EXPLAIN QUERY PLAN of a join whose inner table is an r-tree: the ON terms of an inner join are part of the WHERE clause (`sqlite3ProcessJoin`: WHERE terms first, then ON terms), each offered to xBestIndex once (idxStr B0D1, D1B0); a LEFT JOIN offers its ON terms only.
#[test]
fn rtree_join_terms_are_offered_once_in_where_then_on_order() {
    assert_rows_and_errors_are_what_c_returns(
        "rtree_join_terms_are_offered_once_in_where_then_on_order",
        &[
            "CREATE VIRTUAL TABLE t USING rtree(id, c0, c1);",
            "CREATE TABLE pts(k INTEGER PRIMARY KEY, x);",
            "INSERT INTO t VALUES(1,0,10),(2,5,15);",
            "INSERT INTO pts VALUES(1,3),(2,7),(3,20);",
            "EXPLAIN QUERY PLAN SELECT p.k, t.id FROM pts p JOIN t ON t.c0 <= p.x AND t.c1 >= p.x;",
            "EXPLAIN QUERY PLAN SELECT p.k, t.id FROM pts p, t WHERE t.c0 <= p.x AND t.c1 >= p.x;",
            "EXPLAIN QUERY PLAN SELECT p.k, t.id FROM pts p JOIN t ON t.c0 <= p.x WHERE t.c1 >= p.x;",
            "EXPLAIN QUERY PLAN SELECT p.k, t.id FROM pts p CROSS JOIN t ON t.c0 <= p.x AND t.c1 >= p.x AND t.id > 0;",
            "EXPLAIN QUERY PLAN SELECT p.k, t.id FROM pts p LEFT JOIN t ON t.c0 <= p.x AND t.c1 >= p.x WHERE t.id > 0;",
            "SELECT p.k, t.id FROM pts p JOIN t ON t.c0 <= p.x AND t.c1 >= p.x;",
        ],
        "SCAN p\nSCAN t VIRTUAL TABLE INDEX 2:B0D1\nSCAN p\nSCAN t VIRTUAL TABLE INDEX 2:B0D1\nSCAN p\nSCAN t VIRTUAL TABLE INDEX 2:D1B0\nSCAN p\nSCAN t VIRTUAL TABLE INDEX 2:B0D1\nSCAN p\nSCAN t VIRTUAL TABLE INDEX 2:B0D1 LEFT-JOIN\n1|1\n2|1\n2|2\n",
        &[],
    );
}

