/// `rtreeUpdate` answers SQLITE_LOCKED_VTAB (518, "database table is locked") while a cursor of the r-tree is
/// positioned on a row ("Unable to write to the btree while another cursor is reading from it"): a SELECT that
/// streams from the table and has returned a row keeps it locked until it is stepped to its end or reset; a SELECT
/// with a sorter has read the table to its end before its first row. (C API sequence: h4/lk.txt through h1b/c/drv.)
#[test]
fn rtree_write_is_refused_while_a_scan_is_positioned() {
    let db = TempDb::new("rtree_locked_vtab");
    let conn = Connection::open(&db.0).unwrap();
    conn.query("CREATE VIRTUAL TABLE t USING rtree(id,x0,x1)", &[])
        .unwrap();
    conn.query("INSERT INTO t VALUES(1,1,2),(2,3,4),(3,5,6)", &[])
        .unwrap();
    assert_eq!(conn.total_changes(), 10);
    let mut reader = conn.prepare("SELECT id FROM t").unwrap();
    assert!(matches!(reader.step().unwrap(), crate::StepResult::Row(_)));
    for sql in [
        "INSERT INTO t VALUES(4,1,2)",
        "UPDATE t SET x0=0 WHERE id=1",
        "DELETE FROM t WHERE id=2",
    ] {
        let e = conn.query(sql, &[]).unwrap_err();
        assert_eq!(e.extended_code, 518, "{sql}");
        assert_eq!(e.message, "database table is locked", "{sql}");
    }
    assert_eq!(conn.total_changes(), 10);
    reader.reset().unwrap();
    conn.query("INSERT INTO t VALUES(5,1,2)", &[]).unwrap();
    assert_eq!(conn.total_changes(), 13);
    let mut sorted = conn.prepare("SELECT id FROM t ORDER BY x0 DESC").unwrap();
    assert!(matches!(sorted.step().unwrap(), crate::StepResult::Row(_)));
    conn.query("INSERT INTO t VALUES(6,1,2)", &[]).unwrap();
    assert_eq!(conn.total_changes(), 16);
    sorted.reset().unwrap();
    let mut lookup = conn.prepare("SELECT id FROM t WHERE id=1").unwrap();
    assert!(matches!(lookup.step().unwrap(), crate::StepResult::Row(_)));
    let e = conn.query("INSERT INTO t VALUES(7,1,2)", &[]).unwrap_err();
    assert_eq!(e.extended_code, 518);
    lookup.reset().unwrap();
    drop((reader, sorted, lookup));
    assert!(conn.try_close().is_ok());
}
